function setView(next){view=next;render()}
function roleName(){return role==='club'?data.club.name:role==='coach'?data.coach.name:data.player.name}
function profileLabel(){return role==='club'?'Club workspace · Demo account':role==='coach'?'Verified coach · Demo account':'Player account · Demo account'}
function stat(label,val,sub){return '<div class="stat"><span>'+esc(label)+'</span><strong>'+esc(val)+'</strong><small>'+esc(sub||'')+'</small></div>'}
function panel(title,body,extra){return '<section class="panel"><div class="panel-head"><h3>'+title+'</h3>'+(extra||'')+'</div>'+body+'</section>'}
function pill(s){const cls=/pending|awaiting/i.test(s)?'pending':/reject|declin/i.test(s)?'rejected':/confirm|active|paid|complete|approved/i.test(s)?'active':'';return '<span class="pill '+cls+'">'+esc(s)+'</span>'}
function avatar(name,cls){return '<div class="avatar '+(cls||'')+'">'+esc(initials(name))+'</div>'}
function btn(label,action,id,cls){return '<button type="button" class="btn '+(cls||'light')+'" data-action="'+esc(action)+'" data-id="'+esc(id||'')+'">'+label+'</button>'}
function memberTable(){const rows=data.club.members.map(m=>'<tr><td><div class="person">'+avatar(m.name)+'<div><strong>'+esc(m.name)+'</strong><div class="tiny muted">'+esc(m.city)+' · '+esc(m.sport)+'</div></div></div></td><td>'+esc(m.joined)+'</td><td>'+pill(m.status)+'</td><td><div style="display:flex;gap:5px;flex-wrap:wrap">'+(m.status==='pending'?btn('Approve','approve-member',m.id,'lime')+btn('Decline','decline-member',m.id,'danger'):btn('Remove','remove-member',m.id,'light'))+'</div></td></tr>').join('');
return '<div class="table-wrap"><table><thead><tr><th>Player</th><th>Requested / joined</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
function activityList(){if(!data.club.posts.length)return '<div class="empty"><b>No club activities yet</b>Create an open play or community announcement.</div>';return '<div class="activity-list">'+data.club.posts.map(p=>'<article class="activity"><div><h4>'+esc(p.title)+'</h4><p>'+esc(p.description)+'</p><div class="activity-meta">'+esc(p.type)+' · '+when(p.date)+' · '+esc(p.location)+' · '+(p.published?'Published':'Draft')+'</div></div><div>'+pill(p.published?'Published':'Draft')+'<div style="margin-top:7px">'+btn('Delete','delete-post',p.id,'danger')+'</div></div></article>').join('')+'</div>'}
function sessionCounts(s){const rows=s.registrations||[];return {confirmed:rows.filter(r=>r.status==='confirmed').length,waitlisted:rows.filter(r=>r.status==='waitlisted').length,pending:rows.filter(r=>r.status==='pending').length};}
function sessionRoster(s){const rows=(s.registrations||[]).filter(r=>r.status!=='withdrawn');if(!rows.length)return '<div class="empty">No players have applied yet.</div>';return '<div class="table-wrap"><table><thead><tr><th>Player</th><th>Applied</th><th>Registration</th><th>Manager actions</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><div class="person">'+avatar(r.player)+'<div><strong>'+esc(r.player)+'</strong><div class="tiny muted">'+esc((data.people.find(p=>p.id===r.playerId)||{}).city||'Batangas')+'</div></div></div></td><td>'+esc(r.applied||'—')+'</td><td>'+pill(r.status==='confirmed'?'Confirmed':r.status==='waitlisted'?'Waitlisted':r.status==='pending'?'Pending application':r.status==='declined'?'Declined':'Withdrawn')+'</td><td><div style="display:flex;gap:5px;flex-wrap:wrap">'+(r.status==='pending'?btn('Approve','approve-club-registration',r.id,'lime')+btn('Waitlist','waitlist-club-registration',r.id,'light')+btn('Decline','decline-club-registration',r.id,'danger'):r.status==='waitlisted'?btn('Confirm seat','confirm-club-registration',r.id,'lime')+btn('Decline','decline-club-registration',r.id,'danger'):r.status==='confirmed'?btn('Move to waitlist','waitlist-club-registration',r.id,'light')+btn('Remove','decline-club-registration',r.id,'danger'):btn('Reopen','reopen-club-registration',r.id,'light'))+'</div></td></tr>').join('')+'</tbody></table></div>';}
function clubSessionCards(){if(!data.club.sessions.length)return '<div class="empty"><b>No club sessions yet</b>Create your first venue booking and invite players to join.</div>';return data.club.sessions.map(s=>{const n=sessionCounts(s);return '<section class="panel"><div class="panel-head"><div><h3>'+esc(s.title)+'</h3><div class="tiny muted" style="margin-top:5px">'+esc(s.sport)+' · '+when(s.date)+' · '+esc(s.startTime)+' · '+s.hours+' hour(s)</div></div>'+pill(s.status)+'</div><div class="notice" style="margin-bottom:12px"><strong>'+esc(s.venueName)+'</strong> · '+esc(s.address)+'<br>'+esc(s.court)+' · '+money(s.rate)+'/court-hour · Venue booking: '+esc(s.venueStatus)+'</div><div class="stats">'+stat('Confirmed',n.confirmed,'/'+s.capacity+' seats')+stat('Waitlisted',n.waitlisted,'Waiting for an opening')+stat('Pending',n.pending,'Applications to review')+'</div><div class="panel-head"><h3>Player registrations</h3><span class="tiny muted">'+(n.confirmed+n.waitlisted+n.pending)+' active applications</span></div>'+sessionRoster(s)+'<div class="actions" style="justify-content:flex-start;flex-wrap:wrap">'+(s.venueStatus!=='Confirmed'?btn('Confirm venue booking','confirm-club-venue',s.id,'lime'):'<span class="pill active">Venue confirmed</span>')+btn('Cancel session','cancel-club-session',s.id,'danger')+'</div></section>';}).join('');}
function clubSessionForm(){const v=sessionVenues[0];return panel('Book a venue for your club session','<form data-form="club-session"><div class="form-grid"><div class="field full"><label>Session name *</label><input name="title" required maxlength="100" placeholder="e.g. Friday Pickleball Open Play"></div><div class="field"><label>Sport *</label><select name="sport" id="clubSessionSport">'+v.sports.map(s=>'<option>'+esc(s)+'</option>').join('')+'</select></div><div class="field"><label>Venue / location *</label><select name="venueId" id="clubSessionVenue">'+sessionVenues.map(x=>'<option value="'+x.id+'">'+esc(x.name)+' — '+esc(x.city)+'</option>').join('')+'</select></div><div class="field"><label>Court / facility *</label><select name="court" id="clubSessionCourt">'+v.courts.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></div><div class="field"><label>Date and start time *</label><input name="date" type="datetime-local" required></div><div class="field"><label>Duration (hours)</label><select name="hours"><option value="1">1 hour</option><option value="2" selected>2 hours</option><option value="3">3 hours</option><option value="4">4 hours</option></select></div><div class="field"><label>Player capacity *</label><input name="capacity" type="number" min="2" max="60" value="8" required></div><div class="field full"><label>Session details</label><textarea name="description" maxlength="600" placeholder="What should players know before applying?"></textarea></div></div><div class="notice" style="margin-top:12px">Choose from the sample venues to demonstrate booking at different locations. Rates are illustrative. Creating this session does not reserve a real court or collect payment.</div><div class="actions"><button class="btn lime">Create venue booking & session</button></div></form>');}
function findClubRegistration(registrationId){for(const session of data.club.sessions){const registration=(session.registrations||[]).find(r=>r.id===registrationId);if(registration)return {session,registration};}return null;}
function clubOpenSeats(session){return Math.max(0,Number(session.capacity||0)-sessionCounts(session).confirmed);}
