function activityListPublic(){const rows=data.club.posts.filter(p=>p.published);return rows.length?'<div class="activity-list">'+rows.map(p=>'<article class="activity"><div><h4>'+esc(p.title)+'</h4><p>'+esc(p.description)+'</p><div class="activity-meta">'+esc(p.type)+' · '+when(p.date)+' · '+esc(p.location)+'</div></div></article>').join('')+'</div>':'<div class="empty">No published activities yet.</div>'}
function render(){
 const nav=navs[role];if(!nav.some(x=>x[0]===view))view='overview';
 document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));
 document.getElementById('sideAvatar').textContent=initials(roleName());document.getElementById('sideAvatar').className='avatar '+(role==='club'?'club':role==='coach'?'coach':'');
 document.getElementById('sideName').textContent=roleName();document.getElementById('sideLabel').textContent=profileLabel();document.getElementById('sideCaption').textContent=role==='club'?'Club workspace':role==='coach'?'Coach workspace':'Player area';
 document.getElementById('sideNav').innerHTML=nav.map(n=>'<button type="button" data-view="'+n[0]+'" class="'+(view===n[0]?'active':'')+'"><span class="ico">'+n[1]+'</span>'+n[2]+'</button>').join('');
 document.getElementById('viewTitle').textContent=titles[role][view];document.getElementById('viewDescription').textContent=descriptions[role][view];
 document.getElementById('viewRoot').innerHTML=role==='club'?clubView():role==='coach'?coachView():playerView();
 save();
}
function setRole(next){role=next;view='overview';render()}
document.getElementById('roleSwitch').addEventListener('click',e=>{const b=e.target.closest('[data-role]');if(b)setRole(b.dataset.role)});
document.getElementById('sideNav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});
document.getElementById('viewRoot').addEventListener('click',e=>{
 const g=e.target.closest('[data-go]');if(g){setView(g.dataset.go);return}
 const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,action=b.dataset.action;
 if(action==='approve-member'||action==='decline-member'){const m=data.club.members.find(x=>x.id===id);if(m){m.status=action==='approve-member'?'active':'rejected';toast(m.name+' '+(m.status==='active'?'approved':'declined'));}}
 if(action==='remove-member'){data.club.members=data.club.members.filter(x=>x.id!==id);toast('Demo member removed');}
 if(action==='delete-post'){data.club.posts=data.club.posts.filter(x=>x.id!==id);toast('Demo activity deleted');}
 if(action==='approve-club-registration'||action==='confirm-club-registration'||action==='waitlist-club-registration'||action==='decline-club-registration'||action==='reopen-club-registration'){const found=findClubRegistration(id);if(found){const{session,registration}=found;if(action==='approve-club-registration'||action==='confirm-club-registration'){if(clubOpenSeats(session)>0){registration.status='confirmed';toast(registration.player+' is confirmed for '+session.title+'.');}else{registration.status='waitlisted';toast('Session is full. '+registration.player+' has been moved to the waitlist.');}}else if(action==='waitlist-club-registration'){registration.status='waitlisted';toast(registration.player+' moved to the waitlist.');}else if(action==='decline-club-registration'){registration.status='declined';toast(registration.player+' application declined.');}else{registration.status='pending';toast(registration.player+' application reopened.');}}}
 if(action==='confirm-club-venue'){const s=data.club.sessions.find(x=>x.id===id);if(s){s.venueStatus='Confirmed';toast('Demo venue booking marked confirmed.');}}
 if(action==='cancel-club-session'){const s=data.club.sessions.find(x=>x.id===id);if(s){s.status='Cancelled';toast('Club session cancelled in the demo.');}}
 if(action==='apply-club-session'){const s=data.club.sessions.find(x=>x.id===id);if(s){s.registrations=s.registrations||[];const existing=s.registrations.find(r=>r.playerId==='player-alex');if(existing&&['confirmed','pending','waitlisted'].includes(existing.status)){toast('You already have an application for this session.');}else{s.registrations.push({id:'cr'+Date.now(),playerId:'player-alex',player:data.player.name,status:'pending',applied:'Just now'});toast('Application sent. Your status is Pending until the club reviews it.');}}}
 if(action==='withdraw-club-application'){const found=findClubRegistration(id);if(found){found.registration.status='withdrawn';toast('Your club session application has been withdrawn.');}}
 if(action==='toggle-player-follow'){const active=data.player.followingPlayers.includes(id);data.player.followingPlayers=active?data.player.followingPlayers.filter(x=>x!==id):[...data.player.followingPlayers,id];const p=data.people.find(x=>x.id===id);toast((active?'Unfollowed ':'Following ')+(p?.name||'player'));}
 if(action==='toggle-coach-follow'){const active=data.player.followingCoaches.includes(id);data.player.followingCoaches=active?data.player.followingCoaches.filter(x=>x!==id):[...data.player.followingCoaches,id];toast(active?'You unfollowed Coach Miguel.':'You are now following Coach Miguel.');}
 if(action==='join-club'){if(!data.club.members.some(m=>m.id==='player-alex'))data.club.members.push({id:'player-alex',name:data.player.name,sport:data.player.sport,city:data.player.city,status:'pending',joined:'Just now'});data.player.joinedClub=true;toast('Membership request sent to '+data.club.name);}
 if(action==='confirm-session'||action==='decline-session'){const s=data.coach.sessions.find(x=>x.id===id);if(s){s.status=action==='confirm-session'?'Confirmed':'Declined';s.payment=s.status==='Confirmed'?'Confirmed':'Declined';const pb=data.player.bookings.find(x=>x.id===id);if(pb)pb.status=s.status;toast('Session '+s.status.toLowerCase()+'.');}}
 if(action==='book-coach'){const idNew='s'+Date.now();const booking={id:idNew,coach:data.coach.name,date:future(3,10),hours:1,amount:Number(data.coach.rate),status:'Pending'};data.player.bookings.unshift(booking);data.coach.sessions.unshift({id:idNew,player:data.player.name,date:booking.date,hours:1,amount:booking.amount,payment:'Awaiting verification',status:'Pending'});toast('Demo coaching request created. Switch to Coach to review it.');}
 if(action==='message-coach'){data.coach.messages.push({from:data.player.name,text:'Hi Coach Miguel! I would like to ask about your next available coaching session.',time:'Just now'});data.player.messages.push('Message sent to Coach Miguel');toast('Demo message added to Coach inbox.');}
 if(action==='go'){setView(id);return}
 render();
});
document.getElementById('viewRoot').addEventListener('change',e=>{if(e.target.id==='clubSessionVenue'){const venue=venueById(e.target.value),sport=document.getElementById('clubSessionSport'),court=document.getElementById('clubSessionCourt');sport.innerHTML=venue.sports.map(s=>'<option>'+esc(s)+'</option>').join('');court.innerHTML=venue.courts.map(s=>'<option>'+esc(s)+'</option>').join('');}});
document.getElementById('viewRoot').addEventListener('submit',e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const fd=new FormData(form),v=Object.fromEntries(fd.entries()),kind=form.dataset.form;
 if(kind==='club-session'){const venue=venueById(v.venueId),dt=new Date(v.date);if(Number.isNaN(dt.getTime())){toast('Please enter a valid session date and time.');return;}data.club.sessions.unshift({id:'cs'+Date.now(),title:v.title,sport:v.sport,venueId:v.venueId,venueName:venue.name,address:venue.city,court:v.court,date:dt.toISOString(),startTime:v.date.split('T')[1]||'09:00',hours:Number(v.hours||1),capacity:Number(v.capacity||8),rate:Number(venue.rate),venueStatus:'Pending confirmation',status:'Open',description:v.description||'',registrations:[]});toast('Club session created. Venue booking is pending confirmation.');}
 if(kind==='club-profile'){Object.assign(data.club,{name:v.name,sport:v.sport,city:v.city,phone:v.phone,address:v.address,about:v.about,email:v.email,website:v.website});toast('Demo club profile saved.');}
 if(kind==='club-post'){const date=v.date?new Date(v.date).toISOString():future(7);data.club.posts.unshift({id:'a'+Date.now(),title:v.title,type:v.type,date,location:v.location,description:v.description,published:true});toast('Demo activity published.');}
 if(kind==='coach-profile'){Object.assign(data.coach,{name:v.name,sport:v.sport,city:v.city,experience:Number(v.experience||0),location:v.location,bio:v.bio});toast('Demo coach profile saved.');}
 if(kind==='coach-availability'){data.coach.rate=Number(v.rate||data.coach.rate);data.coach.location=v.location;data.coach.availability.forEach((a,i)=>{a.start=v['start-'+i]||a.start;a.end=v['end-'+i]||a.end;a.active=fd.has('active-'+i)});toast('Demo availability and rates saved.');}
 if(kind==='coach-message'){data.coach.messages.push({from:data.coach.name,text:v.text,time:'Just now'});toast('Demo reply sent in the local conversation.');}
 save();render();
});
document.getElementById('resetDemo').addEventListener('click',()=>{if(!confirm('Reset all demo changes on this browser?'))return;data=fresh();data.club.sessions=sampleClubSessions();role=initialDemoRole;view='overview';try{localStorage.removeItem(STORE)}catch(e){}render();toast('Demo data reset to the original sample.')});
render();
